"""Build original, accessible mechanism diagrams with theme-aware SVG."""
from pathlib import Path
from html import escape as e
import json
root=Path(__file__).resolve().parents[1];out=root/'images/408'
def text(x,y,s,size=22):return f'<text class="dg-text" x="{x}" y="{y}" text-anchor="middle" font-size="{size}">{e(s)}</text>'
def box(x,y,w,h,*lines):return f'<rect class="dg-box" x="{x}" y="{y}" width="{w}" height="{h}" rx="12"/>'+''.join(text(x+w/2,y+h/2+(i-(len(lines)-1)/2)*30+8,s) for i,s in enumerate(lines))
def arrow(x,y,a,b):return f'<path class="dg-arrow" d="M{x} {y} L{a} {b}" marker-end="url(#MARK)"/>'
def save(name,title,desc,body,h=520):
 style='<style>.dg-bg{fill:var(--diagram-bg,#fff)}.dg-box{fill:var(--diagram-fill,#eff4f9);stroke:var(--diagram-line,#356493);stroke-width:2}.dg-arrow{fill:none;stroke:var(--diagram-line,#356493);stroke-width:2.5}.dg-text{fill:var(--diagram-text,#17212f);font-family:SimSun,serif}.dg-accent{fill:var(--diagram-line,#356493)}</style>'
 svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 {h}" role="img" aria-labelledby="{name}-title {name}-desc"><title id="{name}-title">{e(title)}</title><desc id="{name}-desc">{e(desc)}</desc>{style}<defs><marker id="{name}-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path class="dg-accent" d="M0 0 L10 5 L0 10z"/></marker></defs><rect class="dg-bg" width="960" height="{h}" rx="12"/>{text(480,42,title,28)}{body.replace("#MARK", "#"+name+"-arrow")}</svg>\n'
 (out/(name+'.svg')).write_text(svg)
save('cache-address-example','直接映射 Cache：先拆地址，再比较标记','32位字节地址，数据容量16KiB，块64B，256行。地址拆为18位标记、8位行号、6位块内偏移。',text(480,90,'32 位字节地址 · 数据容量 16 KiB · 每块 64 B')+box(50,125,440,85,'标记 Tag：18 位')+box(490,125,240,85,'行号：8 位')+box(730,125,180,85,'块内偏移：6 位')+arrow(610,210,610,265)+box(440,270,340,80,'选中 256 行中的一行')+arrow(270,210,270,370)+box(65,375,410,85,'有效位为 1 且 Tag 相同','才是 Cache 命中')+arrow(820,210,820,375)+box(560,375,350,85,'命中后按偏移取字节')+text(480,500,'行数 = 16384 / 64 = 256；容量不含标记、有效位等开销。',20))
save('paging-address-example','分页地址变换：页号查表，偏移原样保留','4KiB页面，虚拟地址0x12345，页号0x12、偏移0x345，页表映射到页框0x2A，物理地址0x2A345。',text(480,92,'页大小 4 KiB = 2¹² B；虚拟地址 0x12345')+box(70,130,340,85,'虚拟页号 0x12')+box(550,130,340,85,'页内偏移 0x345')+arrow(240,215,240,270)+box(70,275,340,85,'查页表：页号 → 页框号','有效且驻留时得到 0x2A')+arrow(240,360,240,405)+arrow(720,215,720,405)+box(70,410,820,70,'物理地址 = 0x2A × 0x1000 + 0x345 = 0x2A345')+text(480,510,'未驻留须先处理缺页；地址越界或权限错误不能当作普通命中。',20),540)
save('producer-consumer-order','生产者—消费者：先等资源，再进临界区','容量N，empty=N full=0 mutex=1。生产者P(empty) P(mutex)放入 V(mutex) V(full)。消费者P(full) P(mutex)取出 V(mutex) V(empty)。',text(480,90,'初值：empty=N，full=0，mutex=1')+box(35,135,260,100,'生产者','P(empty)：等空位')+box(350,135,260,100,'P(mutex) → 放入','V(mutex)：解锁')+box(665,135,260,100,'V(full)','增加可取产品')+arrow(295,185,345,185)+arrow(610,185,660,185)+box(35,295,260,100,'消费者','P(full)：等产品')+box(350,295,260,100,'P(mutex) → 取出','V(mutex)：解锁')+box(665,295,260,100,'V(empty)','归还空位')+arrow(295,345,345,345)+arrow(610,345,660,345)+text(480,455,'不要持有 mutex 再等待 empty/full：可能阻止对方改变资源计数。',22)+text(480,495,'缓冲区指针和共享数据的修改在互斥区内完成。',20))
save('avl-ll-rotation','AVL 的 LL 型：右旋保持中序顺序','插入10后30失衡，左孩子20的左子树增长，围绕30右旋。右旋后20为根，10和30为左右孩子，中序仍为10、20、30。',text(240,95,'失衡前：在左孩子的左侧增长')+box(290,125,110,60,'30')+box(175,240,110,60,'20')+box(60,355,110,60,'10')+arrow(330,185,250,235)+arrow(215,300,135,350)+arrow(410,265,535,265)+text(470,235,'右旋',23)+box(665,125,110,60,'20')+box(550,285,110,60,'10')+box(780,285,110,60,'30')+arrow(690,185,615,280)+arrow(750,185,825,280)+text(480,460,'旋转不改变中序序列；LR 型须先对左孩子左旋，再对失衡点右旋。',21))
save('dijkstra-relax-example','Dijkstra：松弛不是立刻确定最短路','非负边A到B为2，A到C为5，B到C为1。从A出发，先确定B，再把C的暂定距离由5改为3，最后确定C。',box(90,120,120,70,'A')+box(410,120,120,70,'B')+box(730,120,120,70,'C')+arrow(215,155,405,155)+text(310,130,'2')+arrow(535,155,725,155)+text(630,130,'1')+'<path class="dg-arrow" d="M150 195 Q480 320 790 195" marker-end="url(#MARK)"/>'+text(480,270,'直接边：5')+box(55,335,260,100,'确定 A','d(B)=2，d(C)=5')+box(350,335,260,100,'确定 B','d(C)=min(5,2+1)=3')+box(665,335,260,100,'确定 C','最终距离：0、2、3')+arrow(315,385,345,385)+arrow(610,385,660,385)+text(480,495,'每轮选择未确定顶点中距离最小者；不能将本规则用于任意负权图。',20))
save('kmp-fallback-example','KMP：主串位置不退，模式匹配长度回退','模式ababaca前缀函数为0、0、1、2、3、0、1。已匹配ababa长度5，下一字符失配，先回退到长度3，再按比较决定是否继续回退。',text(480,95,'模式 P = a b a b a c a')+box(90,130,780,70,'前缀函数 π = [0, 0, 1, 2, 3, 0, 1]')+box(55,260,250,90,'已匹配长度 j=5','下一字符比较失败')+box(355,260,250,90,'j ← π[4] = 3','比较 P[3] 与当前字符')+box(655,260,250,90,'若仍失败：j ← π[2]=1','继续比较，不退主串 i')+arrow(305,305,350,305)+arrow(605,305,650,305)+text(480,415,'此图使用 0 起始前缀函数 π；不要直接混用 1 起始 next 数组。',21)+text(480,460,'匹配成功后，主串位置和已匹配长度各前进一位。',21))
save('arp-next-hop-example','跨网发送：ARP 问网关，IP 仍指远端','主机A发送到远端B时，首跳以太网帧目的MAC为本地网关R的MAC，IP目的地址仍为B。路由器下一跳重新封装链路首部。',box(45,120,220,100,'主机 A','先查路由')+box(370,120,220,100,'本地网关 R','下一跳为 R')+box(695,120,220,100,'远端主机 B','位于另一网络')+arrow(270,170,365,170)+arrow(595,170,690,170)+box(45,290,400,105,'A 所在链路：ARP 查询 R 的 IP','获得 R 的 MAC（缓存命中可免查询）')+box(515,290,400,105,'首跳帧：目的 MAC = R 的 MAC','所载 IP 包：目的 IP = B 的 IP')+text(480,460,'普通路由转发逐跳替换链路首部；NAT 等机制的地址改写另论。',21))
save('tcp-send-credit-example','TCP 发送额度：窗口上限减去在途数据','SND.UNA=1000，SND.NXT=1600，cwnd1200，rwnd1800，无回绕。有效窗口1200，在途600，还能发600字节。',text(480,92,'cwnd=1200 B，rwnd=1800 B；有效窗口 min=1200 B')+box(60,155,260,95,'已确认区域','序号 < 1000')+box(320,155,280,95,'已发未确认：600 B','[1000,1600)')+box(600,155,300,95,'尚可发送：600 B','[1600,2200)')+text(320,295,'SND.UNA = 1000',21)+text(610,330,'SND.NXT = 1600',21)+box(80,385,800,75,'可发送量 = max(0, min(cwnd,rwnd) − 在途数据) = 600 B')+text(480,510,'示例忽略序号回绕；不能把窗口上限直接当作本次还能发送的数量。',20),540)
# Attach each diagram once, keeping review IDs and all existing text intact.
mapping={'Cache 三种映射与地址划分':'cache-address-example','分页：页、页框、页表与地址拆分':'paging-address-example','分页虚拟存储：页表字段与地址变换':'paging-address-example','有界缓冲区的生产者—消费者':'producer-consumer-order','AVL 的四种旋转与高度界':'avl-ll-rotation','Dijkstra 的松弛、定点与路径恢复':'dijkstra-relax-example','朴素模式匹配与 KMP 的指针移动':'kmp-fallback-example','ARP：解析同一链路的下一跳':'arp-next-hop-example','TCP 接收窗口、在途数据与发送额度':'tcp-send-credit-example'}
p=root/'data/408-handbook.json';items=json.loads(p.read_text())
for item in items:
 name=mapping.get(item['title'])
 if name and not any(s.get('diagram')==name for s in item['sections']):item['sections'].append({'kind':'example','heading':'机制与步骤图解','diagram':name})
p.write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
print('Built and attached 8 diagrams across 9 knowledge cards.')
